package at.janic.thedarkdimensions.test;

import at.janic.thedarkdimensions.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.decoration.ArmorStand;
import net.minecraft.world.entity.monster.zombie.Zombie;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;

final class SkillTreeTests {
    private static Zombie enemy(GameTestHelper h,double x,double z){var e=h.spawn(EntityTypes.ZOMBIE,new Vec3(x,2,z));e.setNoAi(true);e.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);e.setHealth(100);return e;}
    private static void select(ServerPlayer p,MagicSkill skill,int rank){
        var book=new ItemStack(MagicContent.MASTER_BOOK.get());var d=new MagicData();d.elements=255;d.learned=1L<<skill.ordinal();d.slots[0]=skill.ordinal();d.uses[skill.ordinal()]=new int[]{0,0,8,20,40,70}[rank];d.save(book);p.setItemInHand(InteractionHand.MAIN_HAND,book);clear(p);
    }
    private static void clear(ServerPlayer p){for(var e:MagicElement.values())p.getCooldowns().removeCooldown(p.getCooldowns().getCooldownGroup(new ItemStack(MagicContent.book(e))));p.getCooldowns().removeCooldown(p.getCooldowns().getCooldownGroup(new ItemStack(MagicContent.MASTER_BOOK.get())));}
    private static void aim(ServerPlayer p,LivingEntity e){p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,e.getEyePosition());}
    private static void active(GameTestHelper h,ServerPlayer p){h.onEachTick(()->h.getLevel().getChunkSource().addTicketWithRadius(TicketType.PORTAL,p.chunkPosition(),2));}
    static void graph(GameTestHelper h){
        h.assertTrue(MagicSkill.COUNT==39&&MagicSkill.REWIND.ordinal()==11&&MagicSkill.ELEMENTAL_SURGE.ordinal()==23,"Old 24 skill indices survive; fifteen skills appended");
        for(var element:MagicElement.values()){Set<String> cells=new HashSet<>();int roots=0;for(var skill:MagicSkill.values())if(skill.element()==element){h.assertTrue(cells.add(skill.column()+":"+skill.row()),"No overlapping nodes in "+element+": "+skill);h.assertTrue(skill.column()>=0&&skill.column()<=3&&skill.row()>=0&&skill.row()<=2,"Tree fits the pannable advancement canvas");Set<MagicSkill> path=new HashSet<>();for(var s=skill;s!=null;s=s.parent())h.assertTrue(path.add(s)&&s.element()==element,"Acyclic same-element dependencies");if(skill.parent()==null)roots++;else h.assertTrue(skill.parent().column()<skill.column(),"Edges advance left to right");}h.assertTrue(roots==1,"Exactly one root per element");}
        h.succeed();
    }
    static void migration(GameTestHelper h){
        var book=new ItemStack(MagicContent.MASTER_BOOK.get());net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,book,t->{t.putInt("magic_elements",255);t.putInt("magic_learned",0xffffff);t.putInt("magic_use_11",70);t.putInt("magic_slot_4",11);t.putString("magic_book_id","legacy-book");});
        var d=MagicData.read(book);h.assertTrue(d.learned==0xffffffL&&d.level(11)==5&&d.slots[4]==11,"Legacy int mask, levels, slots and identity migrate");
        int id=MagicSkill.DIMENSION_FOLD.ordinal();d.learned|=1L<<id;d.slots[4]=id;d.uses[id]=70;d.save(book);
        var ops=h.getLevel().registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE);var copy=ItemStack.CODEC.parse(ops,ItemStack.CODEC.encodeStart(ops,book).getOrThrow()).getOrThrow();d=MagicData.read(copy);
        h.assertTrue(d.identity.equals("legacy-book")&&d.knows(id)&&d.level(id)==5&&d.slots[4]==id&&d.knows(0),"Bits above 32 survive real ItemStack codec without losing old progress");
        net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,copy,t->t.putInt("magic_elements",1));d=MagicData.read(copy);h.assertTrue(!d.knows(id)&&d.slots[4]==-1&&d.knows(0),"High indices still respect element ownership");h.succeed();
    }
    static void learning(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var d=new MagicData();d.elements=255;d.learned=1L<<MagicSkill.ENDER_WARD.ordinal();d.save(p.getMainHandItem());var menu=new SpellbookMenu(1,p.getInventory(),0);int id=MagicSkill.DIMENSION_FOLD.ordinal();p.getInventory().setItem(1,new ItemStack(SpellContent.INFUSED_INGOT.get(),2));
        h.assertTrue(!menu.clickMenuButton(p,100+id)&&p.getInventory().getItem(1).getCount()==2,"Cannot buy advanced branch before actual predecessor XP");d=MagicData.read(p.getMainHandItem());d.uses[MagicSkill.ENDER_WARD.ordinal()]=40;d.learned|=1L<<MagicSkill.VOID_PULL.ordinal();d.uses[MagicSkill.VOID_PULL.ordinal()]=8;d.save(p.getMainHandItem());
        h.assertTrue(menu.clickMenuButton(p,100+id)&&p.getInventory().getItem(1).getCount()==1,"One Chronus ingot buys high-index skill");h.assertTrue(!menu.clickMenuButton(p,100+id)&&p.getInventory().getItem(1).getCount()==1,"Duplicate high-index unlock cannot spend twice");
        h.assertTrue(menu.clickMenuButton(p,1000+id*5+4)&&menu.clickMenuButton(p,204),"High-index skill can occupy fifth mixed-wheel slot");d=MagicData.read(p.getMainHandItem());h.assertTrue(d.slots[4]==id&&d.selected==4&&!menu.clickMenuButton(p,1195),"Five-slot bound enforced");
        for(var s:MagicSkill.values()){var x=new MagicData();x.elements=255;for(var requirement:s.requirements()){x.learned|=1L<<requirement.skill().ordinal();x.uses[requirement.skill().ordinal()]=70;}h.assertTrue(x.canLearn(s.ordinal()),"All branches unlock from all their stated prerequisites");}
    }h.succeed();}
    static void embers(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var e=enemy(h,5.5,8.5);aim(p,e);select(p,MagicSkill.EMBER_MARK,5);h.assertTrue(MagicCasting.cast(p,0)&&MagicExpansion.marked(p,e,true),"Glutzeichen casts through existing book selection");
        for(int n=0;n<2;n++){e.damageCooldownTime=0;select(p,MagicSkill.FIRE_RING,1);h.assertTrue(MagicCasting.cast(p,0),"Actual fire ring charges owned mark");}
        h.assertTrue(!MagicExpansion.marked(p,e,true)&&e.getHealth()<90,"Level five mark detonates after two fire spell hits");
        e.damageCooldownTime=0;MagicExpansion.cast(p,MagicSkill.EMBER_MARK,1,e);select(p,MagicSkill.INFERNO,5);h.assertTrue(MagicCasting.cast(p,0)&&!MagicExpansion.marked(p,e,true),"Inferno consumes owned marks");clear(p);h.assertTrue(!MagicCasting.cast(p,0)&&MagicData.read(p.getMainHandItem()).uses[MagicSkill.INFERNO.ordinal()]==70,"No remaining mark means no successful cast or extra XP");h.assertBlockPresent(Blocks.STONE,new BlockPos(5,1,8));
    }h.succeed();}
    static void frost(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var e=enemy(h,5.5,8.5);var near=enemy(h,6.5,8.5);aim(p,e);select(p,MagicSkill.FROST_BIND,5);h.assertTrue(MagicCasting.cast(p,0)&&e.getEffect(MobEffects.SLOWNESS).getAmplifier()==4&&near.hasEffect(MobEffects.SLOWNESS)&&e.hasEffect(KatanaEffects.FROSTED),"Mastered frost binds and reaches nearby targets");
        var boss=h.spawn(at.janic.thedarkdimensions.finale.FinaleContent.REGENT.get(),new Vec3(10.5,2,10.5));boss.setNoAi(true);h.assertTrue(MagicExpansion.cast(p,MagicSkill.FROST_BIND,5,boss)&&boss.getEffect(MobEffects.SLOWNESS).getAmplifier()==0,"Bosses get soft slow instead of immobilization");boss.discard();
        var wither=h.spawn(EntityTypes.WITHER,new Vec3(10.5,2,10.5));wither.setNoAi(true);MagicExpansion.cast(p,MagicSkill.FROST_BIND,5,wither);h.assertTrue(!wither.hasEffect(MobEffects.SLOWNESS),"Vanilla boss effect immunity remains authoritative");wither.discard();
    }h.succeed();}
    static void veil(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();select(p,MagicSkill.WATER_VEIL,1);h.assertTrue(MagicCasting.cast(p,0),"Water veil casts");p.hurtServer(h.getLevel(),h.getLevel().damageSources().magic(),8);h.assertTrue(p.getHealth()==16,"Next health damage is halved");p.damageCooldownTime=0;p.hurtServer(h.getLevel(),h.getLevel().damageSources().magic(),8);h.assertTrue(p.getHealth()==8,"Veil is consumed by exactly one hit");p.setHealth(20);p.damageCooldownTime=0;select(p,MagicSkill.WATER_VEIL,5);MagicCasting.cast(p,0);p.hurtServer(h.getLevel(),h.getLevel().damageSources().magic(),8);h.assertTrue(Math.abs(p.getHealth()-17.2)<.01,"Mastered veil prevents 65 percent");}h.succeed();}
    static void spring(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);p.setHealth(8);p.addEffect(new MobEffectInstance(MobEffects.POISON,100,0));select(p,MagicSkill.HEALING_SPRING,5);h.assertTrue(MagicCasting.cast(p,0),"Stationary healing field casts");h.runAfterDelay(22,()->{try(f){h.assertTrue(p.getHealth()>8&&!p.hasEffect(MobEffects.POISON),"Native server ticks heal and cleanse once at rank five");h.succeed();}});}
    static void chain(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var e=enemy(h,5.5,8.5);var second=enemy(h,8.5,8.5);var third=enemy(h,11.5,8.5);aim(p,e);select(p,MagicSkill.STATIC_CHARGE,5);h.assertTrue(MagicCasting.cast(p,0)&&MagicExpansion.marked(p,e,false)&&MagicExpansion.marked(p,second,false),"Master static spreads to one neighboring enemy");select(p,MagicSkill.CHAIN_LIGHTNING,1);h.assertTrue(MagicCasting.cast(p,0)&&e.getHealth()<100&&second.getHealth()<100&&third.getHealth()<100,"Chain finds consecutive neighbors, not only neighbors of its first target");h.assertTrue(100-e.getHealth()>100-third.getHealth(),"Damage diminishes at each jump");}h.succeed();}
    static void storm(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);var e=enemy(h,5.5,8.5);aim(p,e);select(p,MagicSkill.STORM_FIELD,1);h.assertTrue(!MagicCasting.cast(p,0)&&MagicData.read(p.getMainHandItem()).uses[MagicSkill.STORM_FIELD.ordinal()]==0,"Storm requires a static mark and failure gives no XP");MagicExpansion.cast(p,MagicSkill.STATIC_CHARGE,1,e);h.assertTrue(MagicCasting.cast(p,0)&&e.getHealth()==100,"Storm telegraph does no instant damage");h.runAfterDelay(24,()->{try(f){h.assertTrue(e.getHealth()<100,"Storm starts damaging marked enemies after one-second warning");h.succeed();}});}
    static void anchor(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var start=p.position();select(p,MagicSkill.TIME_ANCHOR,5);h.assertTrue(MagicCasting.cast(p,0),"First press creates anchor");int left=at.janic.thedarkdimensions.resonance.AncientRunes.remaining(p.getCooldowns(),p.getCooldowns().getCooldownGroup(p.getMainHandItem()));h.assertTrue(left==20,"Placement has one-second global cooldown");p.teleportTo(start.x+3,start.y,start.z);var away=p.position();h.setBlock(5,2,5,Blocks.STONE);clear(p);h.assertTrue(!MagicCasting.cast(p,0)&&p.position().equals(away),"Blocked anchor does not teleport or consume another cast");h.setBlock(5,2,5,Blocks.AIR);p.addEffect(new MobEffectInstance(MobEffects.SLOWNESS,100,0));h.assertTrue(MagicCasting.cast(p,0)&&p.position().equals(start)&&!p.hasEffect(MobEffects.SLOWNESS),"Second press returns safely and mastered anchor clears slow");h.assertTrue(MagicData.read(p.getMainHandItem()).uses[MagicSkill.TIME_ANCHOR.ordinal()]==70,"Mastery remains capped after both activations");}h.succeed();}
    static void afterimage(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);var e=enemy(h,5.5,8.5);e.setTarget(p);select(p,MagicSkill.AFTERIMAGE,1);h.assertTrue(MagicCasting.cast(p,0),"Afterimage dash casts");e.setNoAi(false);h.runAfterDelay(8,()->{e.setTarget(p);h.assertTrue(e.getTarget() instanceof ArmorStand,"Hostile mob is distracted by native temporary decoy");h.assertTrue(!e.getTarget().shouldBeSaved(),"Afterimage cannot survive chunk saves or a server restart");});h.runAfterDelay(44,()->{try(f){h.assertTrue(e.getTarget()==p&&h.getLevel().getEntitiesOfClass(ArmorStand.class,p.getBoundingBox().inflate(10)).isEmpty(),"Decoy expires, restores targeting and leaves no persistent entity");h.succeed();}});}
    static void inertia(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);var e=enemy(h,5.5,8.5);var shot=new net.minecraft.world.entity.projectile.hurtingprojectile.SmallFireball(h.getLevel(),e,new Vec3(1,0,0));shot.setPos(p.position().add(-1,1,0));shot.setDeltaMovement(.2,0,0);h.getLevel().addFreshEntity(shot);select(p,MagicSkill.INERTIA_FIELD,5);h.assertTrue(MagicCasting.cast(p,0),"Inertia field casts");double speed=shot.getDeltaMovement().length();MagicExpansion.tick(h.getLevel());h.assertTrue(shot.getDeltaMovement().length()<speed,"Hostile projectile slows without replacing its owner or type");h.runAfterDelay(12,()->{try(f){h.assertTrue(e.hasEffect(MobEffects.SLOWNESS),"Field refreshes temporary enemy slow");shot.discard();h.succeed();}});}
    static void moment(GameTestHelper h){try(var f=DefenseTests.player(h,KatanaContent.FROSTGLEAM.get())){var p=f.player();var book=new ItemStack(MagicContent.CHRONUS_BOOK.get());var d=new MagicData();d.elements=8;d.learned=1L<<MagicSkill.STOLEN_MOMENT.ordinal();d.slots[0]=MagicSkill.STOLEN_MOMENT.ordinal();d.uses[MagicSkill.STOLEN_MOMENT.ordinal()]=70;d.save(book);p.setItemInHand(InteractionHand.OFF_HAND,book);h.assertTrue(MagicCasting.cast(p,1),"Equipped/offhand preparation casts alongside katana");h.assertTrue(at.janic.thedarkdimensions.resonance.AncientRunes.remaining(p.getCooldowns(),p.getCooldowns().getCooldownGroup(book))==20,"Preparation leaves time to use its eight-second window");var e=enemy(h,5.5,8.5);h.assertTrue(KatanaDefense.dodge(p,7),"Real dodge starts");h.assertTrue(!p.hurtServer(h.getLevel(),h.getLevel().damageSources().mobAttack(e),4),"Incoming attack triggers real Perfect Dodge");p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(SpellContent.WATER_BOOK.get()));clear(p);h.assertTrue(MagicCasting.cast(p,1)&&at.janic.thedarkdimensions.resonance.AncientRunes.remaining(p.getCooldowns(),p.getCooldowns().getCooldownGroup(MagicBooks.get(p,1)))==80,"Mastered Perfect Dodge halves the actual next spell cooldown");clear(p);h.assertTrue(MagicCasting.cast(p,1)&&at.janic.thedarkdimensions.resonance.AncientRunes.remaining(p.getCooldowns(),p.getCooldowns().getCooldownGroup(MagicBooks.get(p,1)))==160,"The next real cast no longer receives the single-use credit");h.assertTrue(!MagicExpansion.cast(p,MagicSkill.STOLEN_MOMENT,5,null),"Internal cooldown prevents preparation spam");}h.succeed();}
    static void fold(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var start=p.position();var destination=h.absoluteVec(new Vec3(5.5,2,11.5));p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,destination.add(0,-.1,0));select(p,MagicSkill.DIMENSION_FOLD,5);h.assertTrue(MagicCasting.cast(p,0),"Creates paired passages on loaded safe floors");p.setShiftKeyDown(true);MagicExpansion.tick(h.getLevel());h.assertTrue(p.position().distanceToSqr(start)>9&&p.hasEffect(MobEffects.SPEED),"Crouching enters a passage and gives mastery speed");var arrived=p.position();MagicExpansion.tick(h.getLevel());h.assertTrue(p.position().equals(arrived),"Per-player traversal cooldown prevents portal ping-pong");p.setShiftKeyDown(false);h.assertTrue(!MagicExpansion.teleport(p,start.add(0,2,0)),"Unsupported destination cannot teleport");}h.succeed();}
    static void leapPull(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);var e=enemy(h,5.5,10.5);var side=enemy(h,7.5,10.5);select(p,MagicSkill.VOID_PULL,5);aim(p,e);h.assertTrue(MagicCasting.cast(p,0)&&side.getDeltaMovement().x<0&&side.hasEffect(MobEffects.SLOWNESS),"Void pull moves nearby enemies toward the aimed enemy");p.setYRot(0);p.setXRot(0);p.setOnGround(true);select(p,MagicSkill.THUNDER_LEAP,5);h.assertTrue(MagicCasting.cast(p,0)&&p.getDeltaMovement().y>.6,"Thunder leap launches upward");p.setOnGround(true);p.setDeltaMovement(Vec3.ZERO);h.runAfterDelay(6,()->{try(f){h.assertTrue(e.getHealth()<100,"Landing delivers the actual thunder impact");h.assertBlockPresent(Blocks.STONE,new BlockPos(5,1,10));h.succeed();}});}
    static void ashTrail(GameTestHelper h){var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get());var p=f.player();active(h,p);var e=enemy(h,5.5,6.5);select(p,MagicSkill.ASH_STEP,5);p.setYRot(0);p.setXRot(0);h.assertTrue(MagicCasting.cast(p,0),"Ash dash leaves a short-lived trail");h.runAfterDelay(12,()->{try(f){h.assertTrue(e.getHealth()<100&&e.hasEffect(MobEffects.SLOWNESS),"Mastered trail hurts and slows enemies on its line");h.assertBlockPresent(Blocks.STONE,new BlockPos(5,1,6));h.succeed();}});}
    static void teleportHooks(GameTestHelper h){try(var f=DefenseTests.player(h,MagicContent.MASTER_BOOK.get())){var p=f.player();var start=p.position();var dest=start.add(3,0,0);java.util.function.Consumer<net.neoforged.neoforge.event.entity.EntityTeleportEvent> cancel=e->{if(e.getEntity()==p)e.setCanceled(true);};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(cancel);try{h.assertTrue(!MagicExpansion.teleport(p,dest)&&p.position().equals(start),"Protection hook cancels spell teleport without moving the player");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(cancel);}var targetPos=BlockPos.containing(dest);h.getLevel().setBlockAndUpdate(targetPos,Blocks.WATER.defaultBlockState());h.assertTrue(!MagicExpansion.teleport(p,dest),"Water cannot be a safe spell destination");h.getLevel().setBlockAndUpdate(targetPos,Blocks.AIR.defaultBlockState());h.getLevel().setBlockAndUpdate(targetPos.below(),Blocks.MAGMA_BLOCK.defaultBlockState());h.assertTrue(!MagicExpansion.teleport(p,dest),"Hazardous floor cannot be a safe spell destination");h.assertTrue(at.janic.thedarkdimensions.finale.AshboundRegent.magical(new net.minecraft.world.damagesource.DamageSource(h.getLevel().registryAccess().getOrThrow(MagicExpansion.PULSE),p,p)),"New magic pulses break Regent's magical ward");}h.succeed();}
}
